      s+=U.line(165,213,165,48,U.C.grid)+U.text(177,54,'+z')+U.arrow(165,213,165+155*Math.sin(t),213-155*Math.cos(t),U.C.c)+U.text(205,350,'θ measured from +z')+U.text(205,375,'+z is upward in this sketch');
